  async function open(next){cleanup();preview=false;reviewView=null;sumClear();kr=null;openRow='start';route=next||'reactive';account=w.OESTSettings.get().owner;moveWho();const token=++epoch;try{await chain.catch(()=>{});await repo.adoptLocal().catch(()=>{});data=await repo.get();ensure();if(token!==epoch)return;const [_,mode,id]=route.split('/');if(['new','draft','job','complete'].includes(mode)){if(mode==='draft'){const d=data.reactiveDrafts?.[id];if(!d)throw Error(L('Ten szkic już nie istnieje (zapisany albo usunięty).','This draft no longer exists (saved or deleted).'));draft=structuredClone(d);}else if(mode==='new'){{const problem=id==='blank'?null:C.find(id)?.node;if(id!=='blank'&&(!problem||problem.children))throw Error('REACTIVE_TREE');draft={problemId:problem?id:'',uiTitle:problem?[C.find(id).path.at(-1),problem.label].filter(x=>x&&x!=='Reactive').join(' — '):'',title:problem?.title||'',problem:problem?.sentence||'',building:'Premises',level:'',room:'',note:'',requestedBy:(()=>{const c=who();return c.departments[0]||c.people[0]||'self';})(),jobType:'REPAIR',orderDate:new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,10),requestedName:'',status:'open',quote:false,beforeMediaIds:[],afterMediaIds:[],audioMediaIds:[],draftId:crypto.randomUUID(),createdAt:new Date().toISOString()};pristine=JSON.stringify(draft);await persist(false);route='reactive/draft/'+draft.draftId;w.OESTEkrany.zamien(route);}}else{const job=data.jobs.find(j=>j.id===id);if(!job)throw Error('JOB_MISSING');draft=data.reactiveDrafts?.[id]?structuredClone(data.reactiveDrafts[id]):C.fromJob(job,data.entries.find(e=>e.id===job.entryId));if(mode==='complete'&&!draft.actionId)draft.reportText='';}}else draft=null;render();await renderEvidence();}catch(e){$('v-reactive').innerHTML=panel(L('Nie można otworzyć Reactive: ','Cannot open Reactive: ')+esc(w.OESTBledy?w.OESTBledy.text(e):e.message))+btn(L('Powrót','Back'),'home');$('v-reactive').onclick=()=>navigate('home');}}
