  function infoCounts(root){root.querySelectorAll('[data-ntc]').forEach(el=>{const id=el.dataset.ntc,k=id==='start'?ntScope():ntEnd(),old=id==='start'?(draft?.audioMediaIds||[]).length:0,ph=(draft?.[id==='start'?'beforeMediaIds':'afterMediaIds']||[]).length;const show=n=>{if(!el.isConnected)return;el.hidden=!n&&!ph;el.textContent=[n?'🎤 '+n:'',ph?'📷 '+ph:''].filter(Boolean).join(' · ');el.setAttribute('aria-label',L('Notatki: ','Notes: ')+n+', '+L('zdjęcia: ','photos: ')+ph);};show(old);if(k&&w.OESTNotatki?.summary)w.OESTNotatki.summary(k).then(r=>show((r.all||0)+old),()=>{});});}
